var jitterer = new Random();

var policy = HttpPolicyExtensions
    .HandleTransientHttpError()
    .WaitAndRetryAsync(
        retryCount: 4,
        sleepDurationProvider: attempt =>
        {
            var exponential = TimeSpan.FromSeconds(Math.Pow(2, attempt));
            var jitter = TimeSpan.FromMilliseconds(
                jitterer.Next(0, (int)exponential.TotalMilliseconds / 2));
            return exponential + jitter;
        },
        onRetry: (outcome, timespan, attempt, context) =>
        {
            Console.WriteLine($"Retry {attempt} in {timespan.TotalMilliseconds}ms");
            return Task.CompletedTask;
        });

var circuitBreaker = HttpPolicyExtensions
    .HandleTransientHttpError()
    .CircuitBreakerAsync(
        handledEventsAllowedBeforeBreaking: 5,
        durationOfBreak: TimeSpan.FromSeconds(30),
        onBreak: (outcome, breakDelay) =>
        {
            Console.WriteLine($"Circuit opened for {breakDelay.TotalSeconds}s");
            return Task.CompletedTask;
        },
        onReset: () =>
        {
            Console.WriteLine("Circuit closed — service recovered");
            return Task.CompletedTask;
        });
